package workspace

import (
	"context"
	"os"
	"path/filepath"
	"runtime"
	"testing"
)

func TestImpactGraphUsesLanguageEdgesAndDisclosesUncertaintyAndVariants(t *testing.T) {
	root := t.TempDir()
	files := map[string]string{
		"src/value.ts":       "export const value = 1\n",
		"src/use.ts":         "import { value } from './value'\nexport const used = value\n",
		"src/use.test.ts":    "import { used } from './use'\nconsole.log(used)\n",
		"src/dynamic.ts":     "export const lazy = import(variable)\n",
		"generated/api.go":   "// Code generated by tool. DO NOT EDIT.\npackage generated\n",
		"schema/config.json": "{}\n",
	}
	for name, content := range files {
		path := filepath.Join(root, name)
		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
			t.Fatal(err)
		}
		writeFile(t, path, content)
	}
	graph, err := BuildImpactGraph(root, "prep_graph", []string{"src/value.ts", "schema/config.json"}, ImpactPolicy{}, []VariantPolicy{
		{Name: "linux", Files: []string{"src/**"}, Required: true},
		{Name: "windows", Files: []string{"windows/**"}, Required: true},
	})
	if err != nil {
		t.Fatal(err)
	}
	for _, path := range []string{"src/value.ts", "src/use.ts", "src/use.test.ts"} {
		if !containsString(graph.Affected, path) {
			t.Fatalf("affected %v does not include %s", graph.Affected, path)
		}
	}
	if !containsString(graph.Adapters, "typescript") {
		t.Fatalf("adapters = %v", graph.Adapters)
	}
	if !containsString(graph.Included, "linux") || !containsString(graph.Omitted, "windows") {
		t.Fatalf("variants included=%v omitted=%v", graph.Included, graph.Omitted)
	}
	for _, kind := range []string{"dynamic_or_reflection", "generated_code", "configuration", "variant_omitted"} {
		if !hasImpactRisk(graph.Risks, kind) {
			t.Fatalf("risks = %+v; missing %s", graph.Risks, kind)
		}
	}
	if graph.Coverage.Complete || !graph.RecommendFull {
		t.Fatalf("uncertain graph = %+v", graph)
	}
}

func TestImpactGraphFollowsTypeScriptBarrelWithJavaScriptSpecifiers(t *testing.T) {
	root := t.TempDir()
	files := map[string]string{
		"src/tokenBucket.ts":       "export class TokenBucket {}\n",
		"src/index.ts":             "export { TokenBucket } from './tokenBucket.js'\n",
		"test/tokenBucket.test.ts": "import { TokenBucket } from '../src/index.js'\nnew TokenBucket()\n",
	}
	for name, content := range files {
		path := filepath.Join(root, name)
		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
			t.Fatal(err)
		}
		writeFile(t, path, content)
	}

	graph, err := BuildImpactGraph(root, "prep_barrel", []string{"src/tokenBucket.ts"}, ImpactPolicy{}, nil)
	if err != nil {
		t.Fatal(err)
	}
	for _, path := range []string{"src/tokenBucket.ts", "src/index.ts", "test/tokenBucket.test.ts"} {
		if !containsString(graph.Affected, path) {
			t.Fatalf("affected %v does not include %s", graph.Affected, path)
		}
	}
}

func TestImpactGraphCapsAreExplicit(t *testing.T) {
	root := t.TempDir()
	writeFile(t, filepath.Join(root, "a.ts"), "export const a = 1\n")
	writeFile(t, filepath.Join(root, "b.ts"), "import { a } from './a'\n")
	graph, err := BuildImpactGraph(root, "rev_cap", []string{"a.ts"}, ImpactPolicy{MaxFiles: 1, MaxEdges: 1}, nil)
	if err != nil {
		t.Fatal(err)
	}
	if !graph.Coverage.Capped || !hasImpactRisk(graph.Risks, "graph_cap") || graph.Coverage.Complete {
		t.Fatalf("capped graph = %+v", graph)
	}
}

// The tests stage always runs the whole configured suite, however narrow the
// change: a failing suite the change does not touch still fails the gate.
func TestTestsStageRunsTheFullSuiteAndAFailureFailsTheGate(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("shell fixture is POSIX-specific")
	}
	sandbox, prepared := pipelineSandbox(t, map[string]string{
		"src/value.ts":    "export const value = 1\n",
		"src/use.ts":      "import { value } from './value'\n",
		"src/use.test.ts": "import './use'\n",
	})
	policy := trustedPolicy(t, sandbox.Tree)
	policy.Tests = []CommandPolicy{
		{Name: "unit", Command: []string{"sh", "-c", "test -f src/use.test.ts"}, Covers: []string{"src/**"}},
		{Name: "release", Command: []string{"sh", "-c", "exit 9"}, Covers: []string{"release/**"}},
	}
	full, err := RunVerificationPipeline(context.Background(), sandbox, policy, VerificationRequest{
		Revision: "prep_full", Stages: []string{"tests"},
	}, []PlanStageFile{preparedFile(t, prepared, "src/value.ts")})
	if err == nil {
		t.Fatal("full suite unexpectedly passed")
	}
	if full.FullTestGate != "full_tests_failed" {
		t.Fatalf("full result = %+v", full)
	}
	for _, stage := range full.Stages {
		if stage.Stage == "tests" && stage.TestScope != "full" {
			t.Fatalf("tests stage scope = %q, want full: %+v", stage.TestScope, full.Stages)
		}
	}
}

func preparedFile(t *testing.T, files []PlanStageFile, path string) PlanStageFile {
	t.Helper()
	for _, file := range files {
		if file.Path == path {
			return file
		}
	}
	t.Fatalf("missing prepared file %s", path)
	return PlanStageFile{}
}

func hasImpactRisk(risks []ImpactRisk, kind string) bool {
	for _, risk := range risks {
		if risk.Kind == kind {
			return true
		}
	}
	return false
}
